"""Debian package version comparison. See task.md."""

from __future__ import annotations


class VersionError(ValueError):
    """Raised for a string that is not a valid Debian version."""


_DIGITS = frozenset("0123456789")
_ALPHA = frozenset("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
_REV_CHARS = _DIGITS | _ALPHA | frozenset(".+~")
_UP_CHARS = _REV_CHARS | frozenset("-:")


def _parse(v: str) -> tuple[int, str, str]:
    if not isinstance(v, str):
        raise VersionError(f"version must be a string: {v!r}")
    epoch = 0
    rest = v
    if ":" in v:
        e, rest = v.split(":", 1)
        if not e or not set(e) <= _DIGITS:
            raise VersionError(f"invalid epoch in {v!r}")
        epoch = int(e)
    revision = "0"
    if "-" in rest:
        rest, revision = rest.rsplit("-", 1)
        if not revision or not set(revision) <= _REV_CHARS:
            raise VersionError(f"invalid revision in {v!r}")
    if not rest or rest[0] not in _DIGITS or not set(rest) <= _UP_CHARS:
        raise VersionError(f"invalid upstream version in {v!r}")
    return epoch, rest, revision


def _weight(c: str | None) -> int:
    if c is None:
        return 0
    if c == "~":
        return -1
    if c in _ALPHA:
        return ord(c)
    return ord(c) + 256


def _cmp_str(a: str, b: str) -> int:
    i = j = 0
    while i < len(a) or j < len(b):
        # non-digit part
        while True:
            ca = a[i] if i < len(a) and a[i] not in _DIGITS else None
            cb = b[j] if j < len(b) and b[j] not in _DIGITS else None
            if ca is None and cb is None:
                break
            wa, wb = _weight(ca), _weight(cb)
            if wa != wb:
                return -1 if wa < wb else 1
            if ca is not None:
                i += 1
            if cb is not None:
                j += 1
        # digit part
        si = i
        while i < len(a) and a[i] in _DIGITS:
            i += 1
        sj = j
        while j < len(b) and b[j] in _DIGITS:
            j += 1
        na = int(a[si:i]) if i > si else 0
        nb = int(b[sj:j]) if j > sj else 0
        if na != nb:
            return -1 if na < nb else 1
    return 0


def _cmp_parsed(x: tuple[int, str, str], y: tuple[int, str, str]) -> int:
    if x[0] != y[0]:
        return -1 if x[0] < y[0] else 1
    return _cmp_str(x[1], y[1]) or _cmp_str(x[2], y[2])


def compare(a: str, b: str) -> int:
    """Return -1, 0 or 1 as `a` sorts before, equal to, or after `b`."""
    pa, pb = _parse(a), _parse(b)
    return _cmp_parsed(pa, pb)


def sort_versions(versions: list[str]) -> list[str]:
    """Return `versions` in ascending order; equal versions keep their input order."""
    from functools import cmp_to_key

    parsed = [(_parse(v), v) for v in versions]
    parsed.sort(key=cmp_to_key(lambda x, y: _cmp_parsed(x[0], y[0])))
    return [v for _, v in parsed]
